"""Reword the diagnosis questions founders could not understand.

Founders reported not understanding what Ally was asking. Reading the whole
bank -- 6,340 questions across the reference dump, the thirty psql industry
batches and the six industry seed migrations -- the causes were consistent:

  * jargon a first-time founder has not met: runway, burn, churn, ICP, CAC,
    pipeline, unit economics, P&L, SOP, segment, cadence;
  * short sibling questions that lean on the one before them -- "Does your
    order mix match that?", "Could someone else give your welcome?" -- when
    the engine picks adaptively and never promises to ask them in order;
  * wording compressed past the point of meaning ("What number skill is still
    missing for you?").

2400 of them are reworded here, in plain everyday English. The rest were
read and left alone because a founder would follow them first time.

REVIEWED TWICE. Every rewrite was drafted, then re-read by an independent
reviewer against the original, its red/green flag patterns and its sibling
questions, looking only for a change of meaning, a leading word, an answer
given away or a wrong explanation. 231 drafts were corrected and 17 dropped
(their questions keep their current text). A question shared by several
industries reads the same way in each, apart from naming that industry's work.

THE MEANING DOES NOT MOVE. Every answer is scored against what the question
asks (red/green flag patterns, root cause, problem), so each rewrite asks the
same thing: either/or contrasts, time frames and specifics are kept, and no
rewrite hints at a good answer. Jargon is replaced, or kept with a short
explanation in brackets when the founder may meet the word again. Questions
that test whether a founder knows a term (FIN-201, fixed vs variable costs)
keep the term unexplained, because explaining it would answer it. The
rating-scale and yes/no questions keep their answer shape.

Guarded, like b3c9d15e8a47: a row is updated only when its question_code AND
its current text match, so this is a no-op on a row someone already edited by
hand, and on any database missing a batch. Matched on question_code rather
than id because the industry batches have no fixed ids.

Embeddings are left as they are. They serve the near-repeat filter, which
compares meaning, and the meaning is unchanged; regenerate them with
scripts/embedding_migration/02_regenerate_embeddings.py whenever convenient.

Revision ID: c5e18b3f9a04
Revises: a2e7c481f96b
Create Date: 2026-09-29 15:00:00.000000

"""
